def check_auth() -> Optional[Response]:
    expected = os.environ.get("SCRAPER_PASSWORD", "").strip()
    if not expected:
        return None
    token = request.headers.get("X-Scraper-Auth", "").strip()
    if not token and request.authorization:
        token = request.authorization.password or ""
    if token != expected:
        return jsonify({"ok": False, "error": "دسترسی غیرمجاز (احراز هویت الزامی است)"}), 401
    return None

class FetchError(Exception):
    pass

def worker_wrap_url(worker: str, url: str) -> Tuple[str, Dict[str, str]]:
    """Rewrite a destination for a Worker relay, the way scraper4.php does in
    both aiHttpPrepare() and bslCurlOpts():

        {url} placeholder  ->  substituted with the rawurlencoded target
        otherwise          ->  the target becomes a PATH segment

    plus an X-Target-URL header carrying the real destination.

    The Worker is a reverse proxy keyed on the path. A "?url=" query string
    makes it fetch its own origin, so the upstream never sees the request's
    Authorization header and answers 401 -- which is exactly the failure this
    project hit before the AI transport was ported.
    """
    w = (worker or "").strip().rstrip("/")
    if "{url}" in w:
        return w.replace("{url}", urllib.parse.quote(url, safe="")), {"X-Target-URL": url}
    return w + "/" + url.lstrip("/"), {"X-Target-URL": url}


def fetch_url(url: str, network_cfg: Optional[Dict[str, Any]] = None, timeout: int = 25, headers: Optional[Dict[str, str]] = None) -> str:
    if network_cfg is None:
        cfg = load_data()
        network_cfg = cfg.get("network", {})
    
    proxy_mode = network_cfg.get("proxy_mode", "direct")
    relay_url = network_cfg.get("relay_url", DEFAULT_CLOUDFLARE_RELAY).strip()
    direct_proxy = network_cfg.get("proxy", "").strip()
    verify_tls = network_cfg.get("verify_tls", True)
    
    req_headers = {
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36",
        "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8",
        "Accept-Language": "fa-IR,fa;q=0.9,en-US;q=0.8,en;q=0.7"
    }
    if headers:
        req_headers.update(headers)

    proxies = None
    target_url = url
    
    if proxy_mode == "relay" and relay_url:
        # Same protocol as the AI transport -- see worker_wrap_url().
        target_url, relay_headers = worker_wrap_url(relay_url, url)
        req_headers.update(relay_headers)
    elif proxy_mode == "http" and direct_proxy:
        proxies = {"http": direct_proxy, "https": direct_proxy}

    try:
        resp = requests.get(target_url, headers=req_headers, proxies=proxies, timeout=timeout, verify=verify_tls)
        resp.raise_for_status()
        resp.encoding = resp.apparent_encoding or "utf-8"
        return resp.text
    except Exception as e:
        raise FetchError(f"خطا در دریافت نشانی {url}: {str(e)}")

FA_DIGITS = str.maketrans("0123456789", "۰۱۲۳۴۵۶۷۸۹")


def to_fa(value: Any) -> str:
    """Persian digits, for agent log lines. (The JS toFa() lives in the page.)"""
    return str(value).translate(FA_DIGITS)


# Background Task Registry Helpers
def register_task(task_type: str, title: str, total_steps: int = 100) -> str:
    task_id = f"task_{int(time.time()*1000)}_{uuid.uuid4().hex[:8]}"
    with TASKS_LOCK:
        TASKS[task_id] = {
            "id": task_id,
            "type": task_type,
            "title": title,
            "status": "running",
            "progress": 0,
            "total": total_steps,
            "step": "آغاز عملیات...",
            "logs": [],
            "result": None,
            "error": None,
            "created_at": time.time(),
            "updated_at": time.time(),
            "cancelled": False
        }
    return task_id

def update_task(task_id: str, progress: Optional[int] = None, step: Optional[str] = None, log_msg: Optional[str] = None, result: Optional[Any] = None, error: Optional[str] = None, status: Optional[str] = None):
    with TASKS_LOCK:
        if task_id not in TASKS:
            return
        t = TASKS[task_id]
        if progress is not None:
            t["progress"] = min(100, max(0, int(progress)))
        if step is not None:
            t["step"] = step
        if log_msg:
            t["logs"].append(f"[{datetime.now().strftime('%H:%M:%S')}] {log_msg}")
        if result is not None:
            t["result"] = result
        if error is not None:
            t["error"] = error
            t["status"] = "failed"
        if status is not None:
            t["status"] = status
        t["updated_at"] = time.time()

def is_task_cancelled(task_id: str) -> bool:
    with TASKS_LOCK:
        return TASKS.get(task_id, {}).get("cancelled", False)

# Price calculation engine
def apply_pricing_rules(base_price_toman: float, pct: float = 0, fixed: float = 0, round_to: int = 1000) -> int:
    if base_price_toman <= 0:
        return 0
    p = base_price_toman * (1.0 + (pct / 100.0)) + fixed
    if round_to > 1:
        p = round(p / round_to) * round_to
    return int(max(0, p))

def extract_price_numbers(val: Any) -> int:
    if isinstance(val, (int, float)):
        return int(val)
    if not val:
        return 0
    s = str(val).replace(",", "").replace("،", "").replace("تومان", "").replace("ریال", "").strip()
    digits = "".join(ch for ch in s if ch.isdigit())
    if not digits:
        return 0
    num = int(digits)
    if "ریال" in str(val) and num >= 10:
        num = num // 10
    return num

# Extraction Engine
def parse_html_products(html: str, selectors: Dict[str, str], base_url: str = "") -> List[Dict[str, Any]]:
    soup = BeautifulSoup(html, "html.parser")
    container_sel = selectors.get("container", "").strip()
    if not container_sel:
        for auto_cand in [".product", ".product-item", ".c-product-box", ".product-card", "article.product", "li.product"]:
            if soup.select(auto_cand):
                container_sel = auto_cand
                break
    if not container_sel:
        container_sel = ".product, .product-item, .product-card, article"

    items = soup.select(container_sel)
    results = []
    
    title_sel = selectors.get("title", "").strip()
    price_sel = selectors.get("price", "").strip()
    image_sel = selectors.get("image", "").strip()
    url_sel = selectors.get("url", "").strip()
    sku_sel = selectors.get("sku", "").strip()

    for el in items:
        # Title
        t_el = el.select_one(title_sel) if title_sel else (el.select_one("h2, h3, .title, .product-title, .name") or el)
        title = t_el.get_text(strip=True) if t_el else ""
        if not title and el.name in ["h2", "h3", "a"]:
            title = el.get_text(strip=True)

        # Price
        p_el = el.select_one(price_sel) if price_sel else el.select_one(".price, .amount, .c-price__value, ins .amount, .product-price")
        price_raw = p_el.get_text(strip=True) if p_el else ""
        price = extract_price_numbers(price_raw)

        # Image
        img_el = el.select_one(image_sel) if image_sel else el.select_one("img")
        img_url = ""
        if img_el:
            img_url = img_el.get("data-src") or img_el.get("data-original") or img_el.get("src") or ""
            if img_url and base_url:
                img_url = urllib.parse.urljoin(base_url, img_url)

        # URL
        link_el = el.select_one(url_sel) if url_sel else (el if el.name == "a" else el.select_one("a[href]"))
        link_url = ""
        if link_el and link_el.has_attr("href"):
            link_url = urllib.parse.urljoin(base_url, link_el["href"])

        # SKU
        sku_el = el.select_one(sku_sel) if sku_sel else el.select_one(".sku, [data-sku], .product-sku")
        sku = sku_el.get_text(strip=True) if sku_el else (el.get("data-product-id") or el.get("data-sku") or "")

        if title or img_url or link_url:
            results.append({
                "title": title,
                "price": price,
                "price_raw": price_raw,
                "image": img_url,
                "url": link_url,
                "sku": sku,
                "stock": "in_stock",
                "description": "",
                "specs": {},
                "gallery": [],
                "variations": [],
                "scraped_at": datetime.now().isoformat()
            })
    return results

def run_scrape_worker(task_id: str, config: Dict[str, Any]):
    try:
        url = config.get("url", "").strip()
        pages = int(config.get("pages", 1))
        pag_type = config.get("pag_type", "query")
        pag_val = config.get("pag_val", "page")
        selectors = config.get("selectors", {})
        gap_ms = int(config.get("gap_ms", 350))

        all_products = []
        parsed = urllib.parse.urlparse(url)
        base_origin = f"{parsed.scheme}://{parsed.netloc}"

        for p in range(1, pages + 1):
            if is_task_cancelled(task_id):
                update_task(task_id, status="cancelled", step="توسط کاربر لغو شد.")
                return

            # Build URL for pagination
            if p == 1:
                page_url = url
            else:
                if pag_type == "query":
                    q = urllib.parse.parse_qs(parsed.query)
                    q[pag_val] = [str(p)]
                    new_q = urllib.parse.urlencode(q, doseq=True)
                    page_url = urllib.parse.urlunparse((parsed.scheme, parsed.netloc, parsed.path, parsed.params, new_q, parsed.fragment))
                else:
                    path_clean = parsed.path.rstrip("/")
                    page_url = urllib.parse.urlunparse((parsed.scheme, parsed.netloc, f"{path_clean}/{pag_val}/{p}/", parsed.params, parsed.query, parsed.fragment))

            update_task(task_id, progress=int((p-1)/pages*100), step=f"دریافت صفحه {p} از {pages}...", log_msg=f"دریافت نشانی: {page_url}")
            
            try:
                html = fetch_url(page_url)
                prods = parse_html_products(html, selectors, base_origin)
                all_products.extend(prods)
                update_task(task_id, log_msg=f"استخراج تعداد {len(prods)} محصول از صفحه {p}")
            except Exception as e:
                update_task(task_id, log_msg=f"خطا در صفحه {p}: {str(e)}")

            if p < pages and gap_ms > 0:
                time.sleep(gap_ms / 1000.0)

        # Save to DB
        data = load_data()
        data["last_result"] = all_products
        save_data(data)

        update_task(task_id, progress=100, status="completed", step="پایان استخراج", log_msg=f"مجموعاً {len(all_products)} محصول استخراج و ذخیره شد.", result={"count": len(all_products)})
    except Exception as e:
        update_task(task_id, error=str(e), step="شکست در اجرای اسکرپ")

# Deep Scrape Phase 2 Worker
def run_detail_scrape_worker(task_id: str, detail_selectors: Dict[str, str]):
    try:
        data = load_data()
        products = data.get("last_result", [])
        total = len(products)
        if total == 0:
            update_task(task_id, status="completed", progress=100, step="محصولی برای تکمیل جزئیات یافت نشد.")
            return

        for idx, p in enumerate(products):
            if is_task_cancelled(task_id):
                update_task(task_id, status="cancelled", step="توسط کاربر لغو شد.")
                return

            p_url = p.get("url", "")
            if not p_url:
                continue

            update_task(task_id, progress=int(idx/total*100), step=f"بررسی جزئیات کالا {idx+1} از {total}: {p.get('title','')[:30]}", log_msg=f"دریافت جزئیات: {p_url}")
            try:
                html = fetch_url(p_url)
                soup = BeautifulSoup(html, "html.parser")
                
                # Description
                desc_sel = detail_selectors.get("description", "").strip() or "#description, .description, .product-description, .c-content-expert__text"
                d_el = soup.select_one(desc_sel)
                if d_el:
                    p["description"] = d_el.get_text(strip=True)
                    p["description_html"] = str(d_el)

                # Specs
                specs_sel = detail_selectors.get("specs", "").strip() or ".specifications, .params-list, .c-params"
                s_el = soup.select_one(specs_sel)
                if s_el:
                    specs = {}
                    for row in s_el.select("tr, li, .c-params__list-item"):
                        cells = row.select("td, th, span")
                        if len(cells) >= 2:
                            k = cells[0].get_text(strip=True)
                            v = cells[1].get_text(strip=True)
                            if k and v: specs[k] = v
                    p["specs"] = specs

                # Gallery
                gal_sel = detail_selectors.get("gallery", "").strip() or ".gallery img, .product-gallery img, .woocommerce-product-gallery__image img"
                gallery = []
                for g_img in soup.select(gal_sel):
                    src = g_img.get("data-src") or g_img.get("data-large") or g_img.get("src") or ""
                    if src:
                        gallery.append(urllib.parse.urljoin(p_url, src))
                if gallery:
                    p["gallery"] = gallery

                # Variations
                var_sel = detail_selectors.get("variations", "").strip() or ".variations select, .swatches, .product-variations"
                v_el = soup.select_one(var_sel)
                if v_el:
                    opts = [opt.get_text(strip=True) for opt in v_el.select("option, .swatch-item") if opt.get_text(strip=True)]
                    p["variations"] = opts

            except Exception as e:
                update_task(task_id, log_msg=f"خطا در کالا {idx+1}: {str(e)}")

            time.sleep(0.3)

        data["last_result"] = products
        save_data(data)
        update_task(task_id, progress=100, status="completed", step="پایان فاز ۲", log_msg="تمامی جزئیات با موفقیت استخراج و پیوست شد.")
    except Exception as e:
        update_task(task_id, error=str(e), step="خطا در فاز ۲")

# Multi-Strategy DEDUP Module
def run_dedup_engine(strategy: str = "smart") -> Dict[str, Any]:
    data = load_data()
    products = data.get("last_result", [])
    initial_count = len(products)
    if initial_count == 0:
        return {"ok": True, "initial": 0, "final": 0, "removed": 0, "groups": []}

    seen_keys = {}
    unique_products = []
    duplicate_groups = []

    for idx, p in enumerate(products):
        title = (p.get("title") or "").strip().lower()
        sku = (p.get("sku") or "").strip().lower()
        url = (p.get("url") or "").strip().lower()

        if strategy == "sku" and sku:
            key = f"sku:{sku}"
        elif strategy == "url" and url:
            key = f"url:{url}"
        elif strategy == "title":
            key = f"title:{title}"
        else:  # Smart Strategy
            norm_title = "".join(ch for ch in title if ch.isalnum())
            key = f"smart:{sku}" if sku else f"smart:{norm_title}"

        if key in seen_keys:
            orig_idx = seen_keys[key]
            duplicate_groups.append({
                "original_index": orig_idx,
                "duplicate_index": idx,
                "key": key,
                "title": p.get("title")
            })
        else:
            seen_keys[key] = idx
            unique_products.append(p)

    return {
        "ok": True,
        "initial": initial_count,
        "final": len(unique_products),
        "removed": initial_count - len(unique_products),
        "groups": duplicate_groups,
        "cleaned_products": unique_products
    }

# BaSalam CATFIX Engine
def run_basalam_catfix_worker(task_id: str):
    try:
        data = load_data()
        products = data.get("last_result", [])
        bsl_cfg = data.get("basalam", {})
        default_cat = bsl_cfg.get("category_id") or "1"
        total = len(products)
        
        fixed_count = 0
        for idx, p in enumerate(products):
            if is_task_cancelled(task_id):
                update_task(task_id, status="cancelled", step="لغو شد.")
                return
            
            cur_cat = p.get("basalam_category_id")
            if not cur_cat or str(cur_cat).strip() in ["0", "", "None"]:
                p["basalam_category_id"] = default_cat
                fixed_count += 1
            
            update_task(task_id, progress=int((idx+1)/total*100), step=f"بررسی دسته‌بندی باسلام {idx+1}/{total}")
        
        data["last_result"] = products
        save_data(data)
        update_task(task_id, progress=100, status="completed", step="پایان اصلاح دسته‌بندی باسلام", result={"fixed": fixed_count})
    except Exception as e:
        update_task(task_id, error=str(e))

# ==================== AI HTTP LAYER ====================
# Mirrors scraper4.php aiHttpPrepare(): the destination is handed to the
# Cloudflare Worker as a PATH (or via a {url} placeholder) plus an
# X-Target-URL header -- NOT as a "?url=" query string. Sending it as a query
# parameter makes the worker fetch its own origin, so the upstream never sees
# the Authorization header and answers 401 Unauthorized.

