class AiHttpError(Exception):
    def __init__(self, message: str, mode: str = "", status: int = 0, body: str = ""):
        super().__init__(message)
        self.mode = mode
        self.status = status
        self.body = body


def ai_resolve_endpoint(ai_cfg: Dict[str, Any]) -> str:
    """A user-supplied base URL (gateway mode) always wins over the preset."""
    provider = (ai_cfg.get("provider") or "openrouter").strip().lower()
    base = (ai_cfg.get("base_url") or "").strip().rstrip("/")
    if base:
        if base.endswith("/chat/completions"):
            return base
        return f"{base}/chat/completions"
    return AI_ENDPOINTS.get(provider, AI_ENDPOINTS["openrouter"])


def ai_build_request(endpoint: str, mode: str, ai_cfg: Dict[str, Any]) -> Tuple[str, Dict[str, str], Optional[Dict[str, str]]]:
    """Return (request_url, extra_headers, proxies) for the chosen transport."""
    extra: Dict[str, str] = {}
    proxies: Optional[Dict[str, str]] = None

    if mode == "worker":
        # Do NOT silently substitute a default relay here: that would push the
        # user's API key through a proxy they never configured. PHP errors out
        # on an empty worker URL, and so do we.
        worker = (ai_cfg.get("worker_url") or "").strip().rstrip("/")
        if not worker:
            raise AiHttpError("آدرس Worker خالی است — آن را در بخش «اتصال» وارد کنید", mode)
        req_url, extra = worker_wrap_url(worker, endpoint)
        return req_url, extra, None

    if mode == "proxy":
        px = (ai_cfg.get("proxy") or "").strip()
        if not px:
            raise AiHttpError("آدرس پروکسی خالی است", mode)
        if "://" not in px:
            px = "http://" + px
        proxies = {"http": px, "https": px}
        return endpoint, extra, proxies

    if mode in ("doh", "dns"):
        host = urllib.parse.urlparse(endpoint).hostname or ""
        if mode == "dns":
            ip = (ai_cfg.get("resolve_ip") or "").strip()
            if not ip:
                raise AiHttpError("IP دستی وارد نشده است", mode)
        else:
            ip = doh_resolve(host, (ai_cfg.get("doh_url") or "https://cloudflare-dns.com/dns-query").strip())
        if not ip:
            raise AiHttpError("نام میزبان resolve نشد", mode)
        parts = urllib.parse.urlsplit(endpoint)
        scheme = parts.scheme or "https"
        port = parts.port or (443 if scheme == "https" else 80)
        # Hostname stays in the Host header; only the TCP destination changes.
        pinned = urllib.parse.urlunsplit((scheme, f"{ip}:{port}", parts.path, parts.query, ""))
        extra["Host"] = host
        return pinned, extra, None

    # direct / gateway
    return endpoint, extra, None


def doh_resolve(host: str, doh_url: str, timeout: int = 10) -> str:
    """DNS-over-HTTPS lookup, to survive poisoned DNS resolvers."""
    try:
        sep = "&" if "?" in doh_url else "?"
        r = requests.get(f"{doh_url}{sep}name={urllib.parse.quote(host)}&type=A",
                         headers={"Accept": "application/dns-json"}, timeout=timeout)
        r.raise_for_status()
        for ans in r.json().get("Answer", []) or []:
            if ans.get("type") == 1 and ans.get("data"):
                return str(ans["data"]).strip()
    except Exception:
        pass
    return ""


def ai_extract_text(res_json: Dict[str, Any]) -> str:
    try:
        return (res_json["choices"][0]["message"]["content"] or "").strip()
    except (KeyError, IndexError, TypeError):
        raise AiHttpError("پاسخ مدل ساختار مورد انتظار را نداشت")


def ai_post_once(endpoint: str, payload: Dict[str, Any], api_key: str,
                 mode: str, ai_cfg: Dict[str, Any], timeout: int,
                 raw: bool = False) -> Any:
    """POST a chat payload. Returns the extracted text, or the whole parsed
    response when raw=True (the agent needs message.tool_calls)."""
    req_url, extra, proxies = ai_build_request(endpoint, mode, ai_cfg)
    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json",
        "Accept": "application/json",
    }
    headers.update(extra)
    try:
        resp = requests.post(req_url, headers=headers, json=payload,
                             proxies=proxies, timeout=timeout,
                             verify=bool(ai_cfg.get("verify_tls", True)))
    except requests.RequestException as e:
        raise AiHttpError(f"خطای اتصال: {e}", mode)

    if resp.status_code >= 400:
        detail = (resp.text or "")[:220].replace("\n", " ")
        raise AiHttpError(f"{resp.status_code} {resp.reason}: {detail}", mode, resp.status_code, resp.text)
    try:
        res_json = resp.json()
    except ValueError:
        raise AiHttpError("پاسخ JSON نبود", mode, resp.status_code, resp.text[:220])
    if isinstance(res_json, dict) and res_json.get("error"):
        err = res_json["error"]
        msg = err.get("message") if isinstance(err, dict) else str(err)
        raise AiHttpError(f"خطای ارائه‌دهنده: {msg}", mode, resp.status_code)
    return res_json if raw else ai_extract_text(res_json)


def ai_merge_cfg(ai_cfg: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """Merge the AI section with the network section so both keep working."""
    if ai_cfg is None:
        ai_cfg = load_data().get("ai", {})
    net_cfg = load_data().get("network", {})
    merged = dict(ai_cfg)
    if not merged.get("proxy") and net_cfg.get("proxy"):
        merged["proxy"] = net_cfg["proxy"]
    if not merged.get("worker_url") and net_cfg.get("relay_url"):
        merged["worker_url"] = net_cfg["relay_url"]
    # Configs written before the AI studio existed have no ai.net_mode key at
    # all; honour their network.proxy_mode. Once the AI section names a mode
    # explicitly it must win, otherwise picking "direct" is silently ignored.
    if "net_mode" not in ai_cfg and net_cfg.get("proxy_mode") in ("relay", "worker"):
        merged["net_mode"] = "worker"
    return merged


def ai_transport_order(merged: Dict[str, Any], mode_override: Optional[str] = None) -> List[str]:
    primary = (mode_override or merged.get("net_mode") or "direct").strip()
    order = [primary]
    if merged.get("fallback", True) and not mode_override:
        for m in ("direct", "worker"):
            if m not in order:
                order.append(m)
    return order


def call_ai_completion(prompt: str, system_prompt: str = "", ai_cfg: Optional[Dict[str, Any]] = None,
                       mode_override: Optional[str] = None) -> str:
    """Chat completion with PHP-compatible transports and auto-fallback."""
    merged = ai_merge_cfg(ai_cfg)
    net_cfg = load_data().get("network", {})

    provider = (merged.get("provider") or "openrouter").strip().lower()
    api_key = (merged.get("api_key") or "").strip()
    model = (merged.get("model") or "").strip() or AI_DEFAULT_MODELS.get(provider, "gpt-4o-mini")
    if not api_key and provider != "ollama":
        raise AiHttpError("کلید API وارد نشده است؛ آن را در بخش هوش مصنوعی ذخیره کنید")

    endpoint = ai_resolve_endpoint(merged)
    timeout = int(net_cfg.get("timeout", 25) or 25)
    payload = {
        "model": model,
        "messages": [
            {"role": "system", "content": system_prompt or merged.get(
                "system_prompt", "شما دستیار حرفه‌ای نگارش کاتالوگ فروشگاهی هستید.")},
            {"role": "user", "content": prompt},
        ],
        "temperature": float(merged.get("temperature", 0.7) or 0.7),
        "max_tokens": int(merged.get("max_tokens", 1500) or 1500),
    }

    last_err: Optional[AiHttpError] = None
    for mode in ai_transport_order(merged, mode_override):
        try:
            return ai_post_once(endpoint, payload, api_key, mode, merged, timeout)
        except AiHttpError as e:
            last_err = e
    raise last_err or AiHttpError("تماس با مدل ناموفق بود")


def call_ai_tools(messages: List[Dict[str, Any]], tools: List[Dict[str, Any]],
                  ai_cfg: Optional[Dict[str, Any]] = None,
                  mode_override: Optional[str] = None,
                  raw: bool = False) -> Any:
    """One agent turn. Sends messages + tool specs and returns the raw model
    response (so the caller can read message.tool_calls), or just the text."""
    merged = ai_merge_cfg(ai_cfg)
    net_cfg = load_data().get("network", {})
    provider = (merged.get("provider") or "openrouter").strip().lower()
    api_key = (merged.get("api_key") or "").strip()
    model = (merged.get("model") or "").strip() or AI_DEFAULT_MODELS.get(provider, "gpt-4o-mini")
    if not api_key and provider != "ollama":
        raise AiHttpError("کلید API وارد نشده است؛ آن را در بخش هوش مصنوعی ذخیره کنید")

    payload: Dict[str, Any] = {"model": model, "messages": messages,
                               "temperature": 0.1, "max_tokens": 1200}
    if tools:
        payload["tools"] = tools
        payload["tool_choice"] = "auto"

    endpoint = ai_resolve_endpoint(merged)
    timeout = int(net_cfg.get("timeout", 25) or 25)
    last_err: Optional[AiHttpError] = None
    for mode in ai_transport_order(merged, mode_override):
        try:
            return ai_post_once(endpoint, payload, api_key, mode, merged, timeout, raw=True) \
                if raw else ai_post_once(endpoint, payload, api_key, mode, merged, timeout)
        except AiHttpError as e:
            last_err = e
    raise last_err or AiHttpError("تماس با مدل ناموفق بود")

def run_aicontent_worker(task_id: str, prompt_template: str, selected_indices: List[int]):
    try:
        data = load_data()
        products = data.get("last_result", [])
        total = len(selected_indices)
        if total == 0:
            selected_indices = list(range(len(products)))
            total = len(selected_indices)

        for i, idx in enumerate(selected_indices):
            if is_task_cancelled(task_id):
                update_task(task_id, status="cancelled", step="لغو شد.")
                return
            if idx >= len(products):
                continue

            p = products[idx]
            update_task(task_id, progress=int(i/total*100), step=f"تولید محتوا با هوش مصنوعی برای {i+1} از {total}: {p.get('title','')[:25]}")

            prompt = prompt_template.replace("{title}", p.get("title", "")) \
                                    .replace("{price}", str(p.get("price", ""))) \
                                    .replace("{specs}", json.dumps(p.get("specs", {}), ensure_ascii=False)) \
                                    .replace("{description}", p.get("description", ""))

            try:
                ai_text = call_ai_completion(prompt)
                p["ai_content"] = ai_text
                p["description"] = ai_text
                update_task(task_id, log_msg=f"تولید محتوا برای '{p.get('title')}' با موفقیت انجام شد.")
            except Exception as e:
                update_task(task_id, log_msg=f"خطای هوش مصنوعی برای کالا {idx}: {str(e)}")

            time.sleep(0.5)

        data["last_result"] = products
        save_data(data)
        update_task(task_id, progress=100, status="completed", step="پایان تولید محتوای AI", log_msg="تمامی محتواهای درخواستی تولید و ذخیره شدند.")
    except Exception as e:
        update_task(task_id, error=str(e))

# 4-Way Multi-Store Sync Matrix Engine
def run_sync_matrix_worker(task_id: str):
    try:
        data = load_data()
        products = data.get("last_result", [])
        woo_cfg = data.get("woocommerce", {})
        bsl_cfg = data.get("basalam", {})

        total = len(products)
        matrix = []

        update_task(task_id, progress=10, step="استخراج لیست کالاهای ووکامرس و باسلام جهت تطبیق...")
        
        # Calculate matrix status for each product
        for idx, p in enumerate(products):
            if is_task_cancelled(task_id):
                update_task(task_id, status="cancelled", step="لغو شد.")
                return

            base_price = int(p.get("price") or 0)
            woo_target = apply_pricing_rules(base_price, float(woo_cfg.get("price_pct", 0)), float(woo_cfg.get("price_fixed", 0)), int(woo_cfg.get("round_to", 1000)))
            bsl_target = apply_pricing_rules(base_price, float(bsl_cfg.get("price_pct", 0)), float(bsl_cfg.get("price_fixed", 0)), int(bsl_cfg.get("round_to", 1000)))

            matrix.append({
                "index": idx,
                "title": p.get("title", ""),
                "sku": p.get("sku", ""),
                "source_price": base_price,
                "woo_target_price": woo_target,
                "basalam_target_price": bsl_target,
                "sync_status": "synced" if base_price > 0 else "price_missing",
                "stock_status": p.get("stock", "in_stock")
            })

            update_task(task_id, progress=int(10 + (idx+1)/total*80), step=f"تطبیق قیمت {idx+1}/{total}")

        with open("sync_matrix_result.json", "w", encoding="utf-8") as f:
            json.dump(matrix, f, ensure_ascii=False, indent=2)

        update_task(task_id, progress=100, status="completed", step="پایان ماتریس همگام‌سازی", result={"synced_items": len(matrix)})
    except Exception as e:
        update_task(task_id, error=str(e))

# Deployment Verification & Update Engine
def validate_deploy_source(content: bytes) -> str:
    if not content.startswith((b"#!/", b"#", b"\"\"\"", b"\'\'\'")):
        raise FetchError("فایل دانلودشده شبیه کد Python نیست")
    try:
        text = content.decode("utf-8")
    except UnicodeDecodeError:
        raise FetchError("فایل دانلودشده کدگذاری UTF-8 ندارد")

    required = ("APP_VERSION", "Flask(", '@app.get("/")', "/api/deploy/run")
    missing = [m for m in required if m not in text]
    if missing:
        raise FetchError("نسخه تازه اعتبارسنجی نشد؛ نشانه‌های Scraper4 کامل نیست: " + ", ".join(missing))

    try:
        import ast
        ast.parse(text, filename="<deploy-validate>")
    except SyntaxError as e:
        raise FetchError(f"خطای ساختاری Python در نسخه تازه: {e}")

    for line in text.splitlines():
        if line.strip().startswith("APP_VERSION"):
            parts = line.split("=", 1)
            if len(parts) == 2:
                return parts[1].strip().strip('"\'')
    return "5.0.0"

# ==================== FLASK API ROUTES ====================

@app.get("/")
def route_index():
    auth_err = check_auth()
    if auth_err:
        return auth_err
    return Response(INDEX_HTML, mimetype="text/html; charset=utf-8")

@app.get("/health")
def route_health():
    return jsonify({
        "status": "healthy",
        "version": APP_VERSION,
        "tasks_running": sum(1 for t in TASKS.values() if t.get("status") == "running"),
        "time": time.time()
    })

@app.get("/api/config")
def api_get_config():
    auth_err = check_auth()
    if auth_err:
        return auth_err
    return jsonify({"ok": True, "data": load_data(), "version": APP_VERSION})

@app.post("/api/settings")
def api_save_settings():
    auth_err = check_auth()
    if auth_err:
        return auth_err
    payload = request.get_json(force=True, silent=True) or {}
    cur = load_data()
    for section, sec_data in payload.items():
        if isinstance(sec_data, dict) and section in cur:
            cur[section].update(sec_data)
        else:
            cur[section] = sec_data
    save_data(cur)
    return jsonify({"ok": True, "message": "تنظیمات با موفقیت ذخیره شد"})

@app.post("/api/ui/preferences")
def api_save_ui_preferences():
    auth_err = check_auth()
    if auth_err:
        return auth_err
    prefs = request.get_json(force=True, silent=True) or {}
    data = load_data()
    data.setdefault("ui_preferences", {}).update(prefs)
    save_data(data)
    return jsonify({"ok": True, "preferences": data["ui_preferences"]})

# Profile Management
@app.get("/api/profile")
def api_list_profiles():
    auth_err = check_auth()
    if auth_err:
        return auth_err
    data = load_data()
    return jsonify({"ok": True, "profiles": list(data.get("profiles", {}).keys()), "active": data.get("active_profile", "")})

@app.post("/api/profile")
def api_save_profile():
    auth_err = check_auth()
    if auth_err:
        return auth_err
    body = request.get_json(force=True, silent=True) or {}
    name = body.get("name", "").strip()
    if not name:
        return jsonify({"ok": False, "error": "نام پروفایل الزامی است"}), 400
    data = load_data()
    profiles = data.setdefault("profiles", {})
    snap = {k: data.get(k, {}) for k in PROFILE_SECTIONS}
    # A profile is a site: it owns its source URL, its settings AND the
    # products already extracted for it (mirrors PHP applyProfile's p.products).
    snap["products"] = data.get("last_result", []) or []
    snap["saved_at"] = datetime.now().isoformat()
    profiles[name] = snap
    data["active_profile"] = name
    save_data(data)
    return jsonify({"ok": True, "message": f"پروفایل '{name}' ذخیره شد ({len(snap['products'])} محصول)",
                    "product_count": len(snap["products"])})

PROFILE_SECTIONS = ["woocommerce", "basalam", "ai", "network", "messengers", "selectors", "scrape"]

@app.post("/api/profile/active")
def api_set_active_profile():
    auth_err = check_auth()
    if auth_err:
        return auth_err
    body = request.get_json(force=True, silent=True) or {}
    name = body.get("name", "").strip()
    data = load_data()
    if name and name in data.get("profiles", {}):
        prof = data["profiles"][name]
        for k in PROFILE_SECTIONS:
            if k in prof:
                data[k] = prof[k]
        # Restore this profile's own products into the results tab.
        products = prof.get("products")
        if isinstance(products, list):
            data["last_result"] = products
        data["active_profile"] = name
        save_data(data)
        prods = data.get("last_result", []) or []
        src = (data.get("scrape", {}) or {}).get("url", "")
        return jsonify({"ok": True,
                        "message": f"پروفایل '{name}' بارگذاری شد — {len(prods)} محصول",
                        "product_count": len(prods),
                        "source_url": src,
                        "data": data})
    elif not name:
        # Returning to the default must hand back the full config too, so the
        # UI can refresh instead of keeping the previous profile's values.
        data["active_profile"] = ""
        save_data(data)
        return jsonify({"ok": True, "message": "پروفایل پیش‌فرض فعال شد", "data": data})
    return jsonify({"ok": False, "error": "پروفایل یافت نشد"}), 404

@app.delete("/api/profile/<path:name>")
def api_delete_profile(name: str):
    auth_err = check_auth()
    if auth_err:
        return auth_err
    data = load_data()
    profiles = data.setdefault("profiles", {})
    if name in profiles:
        del profiles[name]
        if data.get("active_profile") == name:
            data["active_profile"] = ""
        save_data(data)
        return jsonify({"ok": True, "message": f"پروفایل '{name}' حذف شد"})
    return jsonify({"ok": False, "error": "پروفایل یافت نشد"}), 404

# Background Tasks APIs
@app.get("/api/tasks")
def api_get_tasks():
    with TASKS_LOCK:
        tasks_list = sorted(list(TASKS.values()), key=lambda x: x.get("created_at", 0), reverse=True)
    return jsonify({"ok": True, "tasks": tasks_list})

@app.get("/api/tasks/<task_id>")
def api_get_task(task_id: str):
    with TASKS_LOCK:
        task = TASKS.get(task_id)
    if not task:
        return jsonify({"ok": False, "error": "وظیفه یافت نشد"}), 404
    return jsonify({"ok": True, "task": task})

@app.post("/api/tasks/<task_id>/cancel")
def api_cancel_task(task_id: str):
    with TASKS_LOCK:
        if task_id in TASKS:
            TASKS[task_id]["cancelled"] = True
            TASKS[task_id]["status"] = "cancelled"
            return jsonify({"ok": True, "message": "درخواست لغو وظیفه ثبت شد"})
    return jsonify({"ok": False, "error": "وظیفه یافت نشد"}), 404

@app.get("/api/tasks/summary")
def api_tasks_summary():
    with TASKS_LOCK:
        total = len(TASKS)
        running = sum(1 for t in TASKS.values() if t.get("status") == "running")
        failed = sum(1 for t in TASKS.values() if t.get("status") == "failed")
        completed = sum(1 for t in TASKS.values() if t.get("status") == "completed")
    return jsonify({"ok": True, "total": total, "running": running, "failed": failed, "completed": completed})

# Scrape APIs
@app.route("/api/scrape", methods=["GET", "POST"])
@app.post("/api/scrape/start")
def api_scrape_start():
    auth_err = check_auth()
    if auth_err:
        return auth_err
    body = request.get_json(force=True, silent=True) or {}
    url = body.get("url", "").strip()
    if not url:
        return jsonify({"ok": False, "error": "نشانی صفحه الزامی است"}), 400

    task_id = register_task("scrape", f"استخراج محصولات از {urllib.parse.urlparse(url).netloc}")
    t = threading.Thread(target=run_scrape_worker, args=(task_id, body), daemon=True)
    t.start()
    return jsonify({"ok": True, "task_id": task_id, "message": "عملیات استخراج در پس‌زمینه آغاز شد"})

