# Storefront Visual Picker Preview
@app.get("/api/picker/preview")
def api_picker_preview():
    auth_err = check_auth()
    if auth_err: return auth_err
    target = request.args.get("url", "").strip()
    if not target:
        return "<p>نشانی نامعتبر است</p>", 400
    try:
        html = fetch_url(target)
        soup = BeautifulSoup(html, "html.parser")
        script_tag = soup.new_tag("script")
        script_tag.string = """
        document.addEventListener('mouseover', function(e) {
            e.target.style.outline = '2px solid #38bdf8';
        });
        document.addEventListener('mouseout', function(e) {
            e.target.style.outline = '';
        });
        document.addEventListener('click', function(e) {
            e.preventDefault();
            e.stopPropagation();
            let path = [];
            let el = e.target;
            while (el && el.nodeType === Node.ELEMENT_NODE && el !== document.body) {
                let sel = el.nodeName.toLowerCase();
                if (el.id) { sel += '#' + el.id; path.unshift(sel); break; }
                if (el.className && typeof el.className === 'string') {
                    sel += '.' + el.className.trim().split(/\s+/).join('.');
                }
                path.unshift(sel);
                el = el.parentElement;
            }
            window.parent.postMessage({type: 'ELEMENT_PICKED', selector: path.join(' > ')}, '*');
        }, true);
        """
        if soup.body: soup.body.append(script_tag)
        return Response(str(soup), mimetype="text/html")
    except Exception as e:
        return f"<p>خطا در بارگذاری پیش‌نمایش: {str(e)}</p>", 500

@app.post("/api/results/update")
def api_update_product():
    body = request.get_json(force=True, silent=True) or {}
    data = load_data()
    if "products" in body and isinstance(body["products"], list):
        data["last_result"] = body["products"]
        save_data(data)
        return jsonify(ok=True, message="فهرست محصولات به‌روزرسانی شد", count=len(body["products"]))
    index = body.get("index")
    prods = data.get("last_result", [])
    if index is not None and 0 <= int(index) < len(prods):
        for k, v in body.items():
            if k != "index": prods[int(index)][k] = v
        save_data(data)
        return jsonify(ok=True, product=prods[int(index)])
    return jsonify(ok=False, error="شاخص محصول نامعتبر است"), 400

@app.post("/api/results/batch")
def api_batch_products():
    body = request.get_json(force=True, silent=True) or {}
    action = body.get("action", "")
    indices = body.get("indices", [])
    data = load_data()
    prods = data.get("last_result", [])
    if action == "delete":
        idx_set = set(int(i) for i in indices)
        data["last_result"] = [p for i, p in enumerate(prods) if i not in idx_set]
        save_data(data)
        return jsonify(ok=True, remaining=len(data["last_result"]))
    return jsonify(ok=False, error="عملیات نامعتبر است"), 400

# ==================== IMPORT (درون‌ریزی) ====================
# Mirrors the PHP build's درون‌ریزی tab: paste or upload CSV/TSV/JSON, map the
# columns, apply the pricing formula, then merge into the results list.

IMPORT_FIELDS = ["title", "price", "sku", "image", "url", "description", "stock", "category"]

# Common Persian/English header aliases -> canonical field
IMPORT_ALIASES = {
    "title": ["title", "name", "product", "product_name", "عنوان", "نام", "نام محصول", "کالا", "محصول"],
    "price": ["price", "amount", "cost", "قیمت", "قیمت (تومان)", "مبلغ", "بها"],
    "sku": ["sku", "code", "product_id", "شناسه", "کد", "کد محصول", "اس‌کی‌یو"],
    "image": ["image", "img", "photo", "picture", "تصویر", "عکس", "تصویر محصول"],
    "url": ["url", "link", "permalink", "لینک", "آدرس", "نشانی"],
    "description": ["description", "desc", "body", "توضیحات", "شرح", "توضیح"],
    "stock": ["stock", "inventory", "status", "موجودی", "وضعیت"],
    "category": ["category", "cat", "دسته", "دسته‌بندی"],
}


def detect_import_format(text: str) -> str:
    stripped = (text or "").lstrip()
    if stripped.startswith("[") or stripped.startswith("{"):
        return "json"
    return "delimited"


def sniff_delimiter(text: str) -> str:
    head = "\n".join((text or "").splitlines()[:5])
    counts = {d: head.count(d) for d in (",", ";", "\t", "|")}
    best = max(counts, key=lambda d: counts[d])
    return best if counts[best] > 0 else ","


def guess_import_mapping(columns: List[str]) -> Dict[str, str]:
    mapping: Dict[str, str] = {}
    for field, aliases in IMPORT_ALIASES.items():
        for col in columns:
            norm = str(col).strip().lower()
            if norm in [a.lower() for a in aliases] and col not in mapping.values():
                mapping[field] = col
                break
    return mapping


def parse_import_text(text: str) -> Dict[str, Any]:
    fmt = detect_import_format(text)
    if fmt == "json":
        payload = json.loads(text)
        if isinstance(payload, dict):
            for key in ("products", "items", "data", "results"):
                if isinstance(payload.get(key), list):
                    payload = payload[key]
                    break
        if not isinstance(payload, list):
            raise ValueError("ساختار JSON باید آرایه‌ای از محصولات باشد")
        rows = [r for r in payload if isinstance(r, dict)]
        columns: List[str] = []
        for r in rows:
            for k in r.keys():
                if k not in columns:
                    columns.append(k)
        return {"format": "json", "columns": columns, "rows": rows}

    delim = sniff_delimiter(text)
    reader = csv.DictReader(io.StringIO(text), delimiter=delim)
    columns = [c for c in (reader.fieldnames or []) if c is not None]
    rows = []
    for raw in reader:
        # DictReader files overflow values under a None key when a row has more
        # fields than the header (e.g. mixed delimiters). A None object key
        # cannot be serialised to JSON, so fold those into a string column.
        clean = {}
        for k, v in raw.items():
            if k is None:
                if isinstance(v, (list, tuple)):
                    clean["_extra"] = delim.join(str(x) for x in v)
                continue
            clean[k] = v
        rows.append(clean)
    return {"format": "delimited", "delimiter": delim, "columns": columns, "rows": rows}


@app.post("/api/import/parse")
def api_import_parse():
    auth_err = check_auth()
    if auth_err:
        return auth_err
    text = ""
    if request.files and "file" in request.files:
        raw = request.files["file"].read()
        text = raw.decode("utf-8-sig", errors="replace")
    else:
        body = request.get_json(force=True, silent=True) or {}
        text = body.get("text", "") or ""
    if not text.strip():
        return jsonify(ok=False, error="متن یا فایلی برای درون‌ریزی ارسال نشد"), 400
    try:
        parsed = parse_import_text(text)
    except (ValueError, json.JSONDecodeError) as e:
        return jsonify(ok=False, error=f"خطا در خواندن داده: {e}"), 400

    columns = parsed["columns"]
    return jsonify(
        ok=True,
        format=parsed["format"],
        delimiter=parsed.get("delimiter", ""),
        columns=columns,
        row_count=len(parsed["rows"]),
        sample=parsed["rows"][:5],
        suggested_mapping=guess_import_mapping(columns),
        fields=IMPORT_FIELDS,
    )


@app.post("/api/import/apply")
def api_import_apply():
    auth_err = check_auth()
    if auth_err:
        return auth_err
    body = request.get_json(force=True, silent=True) or {}
    text = body.get("text", "") or ""
    mapping = body.get("mapping", {}) or {}
    mode = body.get("mode", "append")
    pct = float(body.get("price_pct", 0) or 0)
    fixed = float(body.get("price_fixed", 0) or 0)
    round_to = int(body.get("round_to", 0) or 0)
    # Parity with PHP applyProfile: minPrice filter and titleSuffix transform.
    min_price = float(body.get("min_price", 0) or 0)
    title_suffix = str(body.get("title_suffix", "") or "").strip()
    title_prefix = str(body.get("title_prefix", "") or "").strip()

    if not text.strip():
        return jsonify(ok=False, error="داده‌ای برای درون‌ریزی وجود ندارد"), 400
    try:
        parsed = parse_import_text(text)
    except (ValueError, json.JSONDecodeError) as e:
        return jsonify(ok=False, error=f"خطا در خواندن داده: {e}"), 400

    title_col = mapping.get("title")
    imported: List[Dict[str, Any]] = []
    skipped_min = 0
    for row in parsed["rows"]:
        def pick(field: str) -> str:
            col = mapping.get(field)
            if not col:
                return ""
            val = row.get(col, "")
            return "" if val is None else str(val).strip()

        title = pick("title") or (row.get(title_col, "") if title_col else "")
        if not title and not pick("image") and not pick("url"):
            continue
        price = extract_price_numbers(pick("price"))
        if price > 0 and (pct or fixed or round_to > 1):
            price = apply_pricing_rules(price, pct, fixed, round_to)
        # Drop rows below the minimum price, like PHP's minPrice guard.
        if min_price > 0 and price < min_price:
            skipped_min += 1
            continue
        if title_prefix:
            title = f"{title_prefix} {title}".strip()
        if title_suffix:
            title = f"{title} {title_suffix}".strip()
        imported.append({
            "title": title,
            "price": price,
            "price_raw": pick("price"),
            "sku": pick("sku"),
            "image": pick("image"),
            "url": pick("url"),
            "description": pick("description"),
            "stock": pick("stock") or "in_stock",
            "category": pick("category"),
            "specs": {},
            "gallery": [],
            "variations": [],
            "source": "import",
            "scraped_at": datetime.now().isoformat(),
        })

    if not imported:
        if skipped_min:
            return jsonify(ok=False, error=f"همهٔ {skipped_min} ردیف زیر حداقل قیمت {int(min_price)} تومان بودند"), 400
        return jsonify(ok=False, error="هیچ ردیف معتبری پیدا نشد؛ نگاشت ستون «عنوان» را بررسی کنید"), 400

    data = load_data()
    existing = data.get("last_result", []) or []
    if mode == "replace":
        data["last_result"] = imported
    else:
        data["last_result"] = existing + imported
    save_data(data)
    return jsonify(ok=True, imported=len(imported), total=len(data["last_result"]),
                   mode=mode, skipped_min_price=skipped_min)


