@app.post("/api/chat/send")
def api_chat_send_reply():
    auth_err = check_auth()
    if auth_err: return auth_err
    body = request.get_json(force=True, silent=True) or {}
    thread_id = body.get("thread_id")
    text = body.get("text", "").strip()
    if not text or not thread_id:
        return jsonify({"ok": False, "error": "متن یا شناسه گفتگو ناقص است"}), 400
    
    threads_file = "chat_threads.json"
    threads = []
    if os.path.exists(threads_file):
        try:
            with open(threads_file, "r", encoding="utf-8") as f:
                threads = json.load(f)
        except Exception: pass

    for th in threads:
        if th.get("id") == thread_id:
            th["messages"].append({
                "id": f"m_{int(time.time()*1000)}",
                "sender": "admin",
                "sender_name": "پشتیبانی فروشگاه",
                "text": text,
                "time": datetime.now().strftime("%H:%M"),
                "timestamp": int(time.time())
            })
            th["updated_at"] = int(time.time())
            th["unread_admin"] = False
            break

    with open(threads_file, "w", encoding="utf-8") as f:
        json.dump(threads, f, ensure_ascii=False, indent=2)
    return jsonify({"ok": True, "message": "پاسخ ارسال و ذخیره شد"})

